import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        grid = []
        for _ in range(n):
            grid.append(list(next(iterator)))

        possible = True

        # Check the condition: every '1' must have a '1' below it or to its right.
        # If a '1' is at the bottom row, it must have a '1' to its right.
        # If a '1' is at the rightmost column, it must have a '1' below it.
        # If a '1' is at the bottom-right corner, it cannot exist because 
        # it would fly out of bounds immediately.

        for r in range(n):
            for c in range(n):
                if grid[r][c] == '1':
                    has_right = False
                    has_down = False

                    # Check right
                    if c + 1 < n:
                        if grid[r][c + 1] == '1':
                            has_right = True

                    # Check down
                    if r + 1 < n:
                        if grid[r + 1][c] == '1':
                            has_down = True

                    if not has_right and not has_down:
                        possible = False
                        break
            if not possible:
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
